<template>
 <section class="refund-parcels" v-loading="loading||saving">
  <div class="heading"><div><h3>关联退回包裹</h3><p class="hint">这里只显示本退款的包裹关联摘要；完整仓库回传、实收分配与共同THK操作在包裹详情中处理。</p></div><el-button v-hasPermi="['order:refund:goods']" size="small" @click="openAttach" v-if="Number(policy.manual_enabled)&&refund.goods_state!=='DONE'&&refund.review_state==='APPROVED'">登记退回包裹</el-button></div>
  <el-collapse><el-collapse-item title="包裹关联进度与店铺规则" name="rules">
  <div class="flow">登记物流 → 自动识别包裹 → 归集后共同THK统一下发 → 仓库实收 → 归属分配与入账 → 各退款独立结案</div>
  <p class="hint">店铺规则：{{ Number(policy.enabled)?'允许合包':'未允许新增合包' }} · {{ Number(policy.auto_enabled)?'自动关联已开启':'自动关联未开启' }} · 下发后冻结范围。自动关联只处理同一原平台订单。<router-link v-hasPermi="['order:refund:config']" :to="{path:'/oms-order/afterSaleRules/returns',query:{channelId:refund.channel_id,refundId:refund.id}}">查看本店铺退货规则</router-link></p>
  <div v-if="Number(policy.auto_enabled)&&refund.goods_state!=='DONE'" class="heading"><el-button v-hasPermi="['order:refund:goods']" size="small" :loading="saving" @click="retryAuto">重新检查规则与事实</el-button><el-button v-if="(policy.logistics_sources||[]).includes('MANUAL')" v-hasPermi="['order:refund:goods']" size="small" @click="openAutoLogistics">登记已核实物流并自动关联</el-button></div>
  <el-table v-if="plans.length" :data="plans" size="small"><el-table-column label="退回计划 / SKU" min-width="200"><template slot-scope="s">#{{ s.row.id }} · {{ s.row.sku_sn }}</template></el-table-column><el-table-column label="包裹关联进度" min-width="170"><template slot-scope="s"><el-tag :type="s.row.parcel_state==='NEED_CHECK'?'warning':s.row.parcel_state==='LINKED'?'success':'info'" size="small">{{ stateLabels[s.row.parcel_state]||'等待包裹关联' }}</el-tag></template></el-table-column><el-table-column label="处理提示 / 下一步" min-width="300"><template slot-scope="s">{{ s.row.parcel_error||(s.row.parcel_state==='LINKED'?(s.row.actual?'与包裹内退款共用THK；进入包裹详情查看':'已加入包裹，等待统一下发THK'):(Number(policy.auto_enabled)?'满足物流、审核及退回安排条件后自动检查':'登记包裹，或到店铺设置开启自动关联')) }}<el-button v-if="s.row.parcel_state==='NEED_CHECK'" v-hasPermi="['order:refund:goods']" type="text" @click="$emit('review',s.row.id)">核对合包归属</el-button></template></el-table-column></el-table>
  </el-collapse-item></el-collapse>
  <el-alert v-if="error" :title="error" type="warning" :closable="false"/>
  <el-empty v-if="!rows.length&&!error" description="尚未关联包裹。先明确退回安排；自动合包开启时将按店铺规则检查，否则请登记退回包裹。" :image-size="55"/>
  <article v-for="p in rows" :key="p.id" class="parcel parcel-brief">
   <div class="heading"><div><b>{{ p.carrier_code }} · {{ p.waybill }}</b><p class="hint">{{ p.parcel_sn }} · {{ refundCount(p) }} 张退款单共用包裹</p></div><el-button type="primary" size="small" @click="openParcel(p)">查看包裹及处理实收</el-button></div>
   <div class="own-scope"><b>本退款在此包裹</b> · 计划 {{ parcelScope(p,refund.id).planned }} 件 · 实收 {{ receiptText(parcelScope(p,refund.id).accepted,scopePending(p,refund.id)) }} · 已入账 {{ parcelScope(p,refund.id).posted }} 件</div>
   <p v-if="scopePending(p,refund.id)" class="warning">关联包裹存在实收待分配，当前退款单的实收数量尚未确定。</p>
   <p v-for="m in (p.members||[]).filter(m=>Number(m.refund_id)===Number(refund.id)&&allocationOutcome(p,m.plan_id))" :key="m.id" class="warning">{{ allocationOutcome(p,m.plan_id) }}</p>
   <p class="hint">整个包裹：计划 {{ expected(p) }} 件 · 已确认实收 {{ sum(p,'accepted_quantity') }} 件 · 待分配 {{ waiting(p) }} 件。包裹数量不等于本退款实收。</p>
  </article>
  <el-drawer title="退回包裹详情" :visible.sync="parcelVisible" size="min(1180px,96vw)" append-to-body :wrapper-closable="false" custom-class="refund-parcel-drawer">
   <div class="parcel-workspace" v-loading="loading||saving">
  <article v-for="p in detailRows" :key="p.id" class="parcel parcel-detail">
   <div class="heading"><b>{{ p.carrier_code }} · {{ p.waybill }}</b><el-tag :type="refundCount(p)>1?'warning':'info'" size="small">{{ refundCount(p)>1?'合包退回':'退回包裹' }} · {{ refundCount(p) }} 张退款单</el-tag><el-button v-hasPermi="['order:refund:goods']" type="text" @click="openTransport(p)">登记物流进度</el-button></div>
   <p class="hint">包裹 {{ p.parcel_sn }} · 接收仓 {{ p.store_code }} · 货主 {{ p.owner_code }} · {{ transportLabels[p.transport_state] }}</p><p class="hint">退回地址 {{ p.return_address||'—' }} · 联系信息 {{ p.return_contact||'—' }}</p>
   <el-alert title="以下为整个退回包裹，涉及全部关联TK" description="分配实收、查询仓库和共同截单均在包裹范围内处理；各退款的资金与结案仍独立。" type="info" :closable="false" show-icon/>
   <div class="parcel-metrics"><div><span>合包计划</span><b>{{ expected(p) }} 件</b></div><div><span>{{ p.receipt_limit_reached?'当前记录回传':'仓库已回传' }}</span><b>{{ reported(p) }} 件</b></div><div class="pending"><span>实收待分配</span><b>{{ waiting(p) }} 件</b></div><div><span>已确认实收</span><b>{{ sum(p,'accepted_quantity') }} 件</b></div><div><span>已入账</span><b>{{ sum(p,'posted_quantity') }} 件</b></div></div>
   <p v-if="!p.receipt_limit_reached" class="hint">{{ reportRemainder(p) }}；仓库回传不等于已分配入账。拒绝的回传不计入上述回传数量。</p>
   <div class="summary"><b>共同退货入库单 {{ p.warehouse_document?p.warehouse_document.return_sn:'待统一生成' }}</b><div v-if="p.warehouse_document" class="hint">{{ dispatchLabels[p.warehouse_document.dispatch_state]||p.warehouse_document.dispatch_state }} · {{ p.warehouse_document.cancel_state==='CONFIRMED'?'整单剩余已截停':'截单：'+({NONE:'未申请',PENDING:'申请中',UNKNOWN:'结果待确认',REJECTED:'仓库拒绝',CONFIRMED:'已确认'})[p.warehouse_document.cancel_state] }} · 仓库单号 {{ p.warehouse_document.external_order||'待确认' }}</div><div v-else class="hint">等待归集至 {{ p.dispatch_after||'人工确认' }}；立即下发会冻结本包裹全部来源明细。</div><div v-if="p.warehouse_document&&p.warehouse_document.last_error" class="warning">{{ p.warehouse_document.last_error }}</div></div>
   <p v-if="p.warehouse_document"><router-link :to="{path:'/oms-supplychain/wmsTickets',query:{sn:p.warehouse_document.return_sn,documentId:p.warehouse_document.ticket_id}}">查看共同THK明细</router-link> · <router-link :to="{path:'/oms-supplychain/wmsLogs',query:{numberType:'DOCUMENT',number:p.warehouse_document.return_sn,allTime:'true'}}">共同THK仓库交互日志</router-link></p>
   <div class="document-actions" v-hasPermi="['order:refund:goods']"><el-button v-if="!p.warehouse_document" size="small" type="primary" @click="openDocument(p,'dispatch')">确认范围并统一下发</el-button><template v-else><el-button size="small" @click="openDocument(p,'query')">查询共同THK</el-button><el-button size="small" v-if="p.warehouse_document.dispatch_state==='FAILED'" @click="openDocument(p,'retry')">重试共同THK</el-button><el-button size="small" @click="openDocument(p,'posting')">核对原实收入账</el-button><el-button size="small" v-if="p.warehouse_document.cancel_state==='CONFIRMED'" @click="openDocument(p,'rebuild')">重排剩余退回</el-button><el-button size="small" type="warning" v-if="p.warehouse_document.cancel_state!=='CONFIRMED'" @click="openDocument(p,'cancel')">截停共同THK</el-button></template></div>
   <div v-for="e in p.receipts.filter(e=>e.state==='WAIT_ALLOCATION')" :key="e.id" class="pending-receipt"><el-alert :title="`实收数量待分配至退款单 · ${e.quantity} 件`" :description="allocationReason(p,e)" type="warning" :closable="false" show-icon/><p class="hint">仓库消息 {{ e.message_id }} · 未分配部分不增加库存</p><el-button v-hasPermi="['order:refund:goods']" type="primary" size="small" @click="openReceipt(p,e)">人工分配本次实收</el-button><el-button v-hasPermi="['order:refund:goods']" size="small" @click="previewAutomatic(p,e)">按当前规则预览分配</el-button></div>
   <h4>关联退款与已确认实收</h4>
   <el-table :data="p.members" size="small"><el-table-column label="退款 / 原订单" min-width="260"><template slot-scope="s"><router-link :to="{path:'/oms-order/businessRefunds',query:{id:s.row.refund_id}}">{{ s.row.refund_sn }}</router-link><el-tag v-if="Number(s.row.refund_id)===Number(refund.id)" size="mini">当前TK</el-tag><div class="hint">{{ s.row.order_sn }}</div></template></el-table-column><el-table-column label="SKU / 发货来源" min-width="180"><template slot-scope="s">{{ s.row.sku_sn }}<div class="hint">原发货明细 #{{ s.row.source_line_id }} · {{ s.row.association_mode==='AUTO'?'自动关联':'人工关联' }}</div></template></el-table-column><el-table-column label="仓库安排" min-width="260"><template slot-scope="s">明细行 {{ s.row.id }} · {{ s.row.return_sn||'待统一生成THK' }}<div class="hint">{{ s.row.cancel_state==='CONFIRMED'?'剩余已截停':s.row.receipt_state==='COMPLETED'?'实收已完成':dispatchLabels[s.row.dispatch_state]||'待下发' }}</div></template></el-table-column><el-table-column prop="quantity" label="安排数量" width="90"/><el-table-column label="已确认实收" min-width="190"><template slot-scope="s">{{ receiptText(s.row.accepted_quantity,sourcePending(p,s.row)) }}<div class="hint">{{ allocationOutcome(p,s.row.plan_id) }}</div></template></el-table-column><el-table-column prop="posted_quantity" label="已入账" width="90"/></el-table>
   <el-alert v-if="p.receipt_limit_reached" title="回传较多，仅展示近期回传和优先待核对记录；完整记录请查仓库交互日志。" type="info" :closable="false"/><p class="hint">同一计划的多次安排保留原记录，计划范围按计划去重，不把旧单截停数量与新单相加。</p>
   <h4>仓库逐次回传与分配记录</h4>
   <el-table :data="p.receipts" size="small" empty-text="尚无仓库回传"><el-table-column type="expand"><template slot-scope="s"><el-table :data="allocationRows(p,s.row)" size="mini" empty-text="本次尚无已确认的退款分配结果"><el-table-column prop="refund_sn" label="分配至退款单" min-width="260"/><el-table-column v-if="allocationMetadata(s.row).method!=='RULE_PARTIAL'" prop="good_qty" label="良品"/><el-table-column v-if="allocationMetadata(s.row).method!=='RULE_PARTIAL'" prop="bad_qty" label="次品"/><el-table-column v-if="allocationMetadata(s.row).method==='RULE_PARTIAL'" label="分配优先时间" min-width="190"><template slot-scope="r">{{ r.row.refund_created }}<div class="hint">{{ r.row.priority_basis==='OMS_CREATED_FALLBACK'?'OMS创建时间（平台申请时间缺失）':'平台退款申请时间' }}</div></template></el-table-column><el-table-column v-if="allocationMetadata(s.row).method==='RULE_PARTIAL'" prop="assigned" label="本次分配"/><el-table-column v-if="allocationMetadata(s.row).method==='RULE_PARTIAL'" prop="remaining" label="分配后待退回"/></el-table></template></el-table-column><el-table-column prop="message_id" label="仓库消息" min-width="180"/><el-table-column prop="quantity" label="本次数量" width="100"/><el-table-column label="归属处理" min-width="220"><template slot-scope="s">{{ allocationMetadata(s.row).method==='RULE_PARTIAL'&&s.row.state==='ALLOCATED'?'已按规则自动分配':receiptLabels[s.row.state]||s.row.state }}<div class="hint" v-if="allocationMetadata(s.row).policy_revision!=null">规则版本 {{ allocationMetadata(s.row).policy_revision }} · {{ allocationMetadata(s.row).reason }}</div></template></el-table-column><el-table-column label="核对依据" min-width="180"><template slot-scope="s">{{ s.row.reason||'—' }}<div class="hint">{{ s.row.evidence }}</div></template></el-table-column><el-table-column label="操作" width="145"><template slot-scope="s"><el-button v-if="s.row.state==='WAIT_ALLOCATION'" v-hasPermi="['order:refund:goods']" type="text" @click="openReceipt(p,s.row)">分配本次实收</el-button></template></el-table-column></el-table>
  </article>
   <el-button @click="parcelVisible=false">返回退款单</el-button>
   </div>
  </el-drawer>
  <el-dialog title="按当前规则预览实收分配" :visible.sync="previewVisible" width="min(1000px,96vw)" append-to-body :close-on-click-modal="false">
   <el-alert :title="preview.status==='READY'?'当前规则可分配，确认前不增加库存':'当前不满足自动分配条件'" :description="preview.reason" :type="preview.status==='READY'?'success':'warning'" :closable="false" show-icon/>
   <p class="hint">规则版本 {{ preview.policy_revision }} · 仓库明细行号优先；无行号时按退款申请时间先后，同时间按TK及来源顺序。未提供有效平台申请时间时采用OMS创建时间，已在下方标明。</p>
   <el-table :data="preview.rows||[]" size="small"><el-table-column prop="refund_sn" label="退款单" min-width="265"/><el-table-column label="分配优先时间" min-width="190"><template slot-scope="s">{{ s.row.refund_created }}<div class="hint">{{ s.row.priority_basis==='OMS_CREATED_FALLBACK'?'OMS创建时间（平台申请时间缺失）':'平台退款申请时间' }}</div></template></el-table-column><el-table-column prop="quantity" label="计划"/><el-table-column prop="assigned" label="本次分配"/><el-table-column prop="remaining" label="分配后待退回"/></el-table>
   <p class="warning">仅分配本次仓库已收商品，剩余数量继续待退回，不会自动结案或同意平台退款。配置或包裹发生变化时需重新预览。</p>
   <el-checkbox v-if="preview.status==='READY'" v-model="previewConfirmed">已核对分配结果，确认按当前规则分配实收并入账</el-checkbox>
   <span slot="footer"><el-button @click="previewVisible=false">返回</el-button><el-button v-hasPermi="['order:refund:goods']" type="primary" :loading="saving" :disabled="preview.status!=='READY'||!previewConfirmed" @click="applyAutomatic">确认按规则分配</el-button></span>
  </el-dialog>
  <el-dialog title="共同退货入库单处理" :visible.sync="documentVisible" width="min(860px,96vw)" append-to-body :close-on-click-modal="false">
   <el-alert :title="documentAction==='cancel'?'整单截停影响下方全部退款的剩余收货；保留已实收和已入账，不代表物流拦截成功。':documentAction==='rebuild'?'只为尚未实收的来源生成新的共同THK，已实收保留；必须先处理全部待核对回传。':documentAction==='dispatch'?'确认后统一下发一张THK，范围冻结；不会自动同意平台退款。':'查询或重试同一张THK，不新建单据。'" type="warning" :closable="false" show-icon/>
   <p>{{ documentParcel.parcel_sn }} · {{ documentParcel.waybill }}</p><el-table :data="documentParcel.members||[]" size="small"><el-table-column prop="refund_sn" label="受影响退款" min-width="260"/><el-table-column prop="sku_sn" label="SKU"/><el-table-column prop="quantity" label="计划" width="70"/><el-table-column prop="posted_quantity" label="已入账" width="80"/></el-table>
   <el-form label-width="100px" style="margin-top:20px"><el-form-item label="处理依据" required><el-input v-model.trim="documentForm.reason" type="textarea" maxlength="500"/></el-form-item><el-form-item label="核对凭证" required><el-input v-model.trim="documentForm.evidence" maxlength="1000"/></el-form-item><el-form-item><el-checkbox v-model="documentForm.confirmed_shared">已核对全部关联退款、数量与共同THK影响范围</el-checkbox></el-form-item></el-form><span slot="footer"><el-button @click="documentVisible=false">返回</el-button><el-button type="primary" :loading="saving" :disabled="!documentForm.confirmed_shared" @click="submitDocument">确认{{ documentAction==='cancel'?'整单截停':documentAction==='dispatch'?'统一下发':'处理' }}</el-button></span>
  </el-dialog>
  <el-dialog :title="action==='auto-logistics'?'登记已核实物流并自动关联':action==='attach'?'登记退回包裹':action==='receipt'?'分配本次实收':'登记退回物流进度'" :visible.sync="visible" width="min(1000px,96vw)" append-to-body :close-on-click-modal="false">
   <el-alert :title="action==='receipt'?'确认后按分配结果更新各退款单，并按原库存来源入账；未分配部分不会增加库存。拒绝回传不代表实物已处置。':'此操作只登记包裹关联或物流事实，不同意平台退款、不增加库存、不自动下发仓库。'" type="info" :closable="false"/>
   <el-form label-width="125px" class="form">
    <template v-if="['attach','auto-logistics'].includes(action)">
     <el-form-item label="本退款退回计划" required><el-select v-model="form.plan_id" style="width:100%"><el-option v-for="p in plans" :key="p.id" :value="p.id" :label="`#${p.id} · ${p.sku_sn} · ${p.quantity}件 · ${p.store_code}`"/></el-select></el-form-item>
     <el-form-item label="快递编码" required><el-select v-model="form.carrier_code" filterable allow-create default-first-option @change="clearCandidates"><el-option v-for="(name,key) in carriers" :key="key" :value="key" :label="name+' · '+key"/></el-select></el-form-item>
     <el-form-item label="完整寄回运单" required><el-input v-model.trim="form.waybill" maxlength="50" @input="clearCandidates"/></el-form-item>
     <el-form-item v-if="action==='attach'"><el-button :loading="checking" @click="checkCandidates">检查相同运单</el-button><span v-if="checked&&!candidates.length" class="hint">未找到相同快递和运单，将建立独立退回包裹。</span></el-form-item>
     <el-form-item v-if="action==='attach'&&candidates.length" label="确认加入包裹" required><el-radio-group v-model="form.join_parcel_id"><el-radio v-for="p in candidates" :key="p.id" :label="p.id">{{ p.parcel_sn }} · {{ p.store_code }} · 货主 {{ p.owner_code }} · 已关联 {{ p.member_count }} 条安排</el-radio></el-radio-group><p class="hint">仅在确认同一实际包裹、接收仓和货主一致时加入。退回地址、联系信息及仓库货主须一致，THK冻结后不可直接追加。</p></el-form-item>
     <el-form-item v-if="policy.scope==='CROSS_ORDER_MANUAL'&&action==='attach'"><el-checkbox v-model="form.buyer_verified">已核实跨订单商品属于同一买家、同一实际退回包裹</el-checkbox></el-form-item>
    </template>
    <el-form-item v-if="action==='transport'" label="物流状态"><el-select v-model="form.transport_state"><el-option v-for="(name,key) in transportLabels" :key="key" :value="key" :label="name"/></el-select></el-form-item>
    <template v-if="action==='receipt'">
     <p class="hint">{{ selected.carrier_code }} · {{ selected.waybill }} · 仓库消息 {{ receipt.message_id }}</p>
     <el-form-item label="核对结论"><el-radio-group v-model="form.decision"><el-radio label="REJECT">拒绝本次回传入账</el-radio><el-radio label="ALLOCATE">分配至各退款单并确认实收</el-radio></el-radio-group></el-form-item>
     <div v-if="form.decision==='ALLOCATE'" v-for="(line,index) in receiptLines" :key="index" class="source-line">
      <b>原回传第 {{ index+1 }} 行 · {{ line.sku }} · 批次 {{ line.batch||'未提供' }} · 良品 {{ line.good }} / 次品 {{ line.bad }}</b>
      <div v-for="(a,i) in form.allocations.filter(a=>a.line_index===index)" :key="i" class="allocation"><el-select v-model="a.task_id" placeholder="选择原THK的退款来源" style="flex:1;min-width:260px"><el-option v-for="m in eligibleSources(selected,receipt,line)" :key="m.id" :value="m.task_id" :label="`${m.refund_sn} · ${m.return_sn} · 本单剩余${Math.max(0,Number(m.quantity)-Number(m.accepted_quantity||0))}件`"/></el-select><span>良品</span><el-input-number v-model="a.good_qty" :min="0" :precision="0" size="small"/><span>次品</span><el-input-number v-model="a.bad_qty" :min="0" :precision="0" size="small"/><el-button type="text" @click="removeAllocation(a)">移除</el-button></div><el-button type="text" @click="form.allocations.push({line_index:index,task_id:null,good_qty:0,bad_qty:0})">增加退款分配行</el-button>
     </div>
     <el-alert v-if="form.decision==='ALLOCATE'" :title="allocationIssue||'本次良品、次品数量已全部分配；确认后按各退款原库存来源入账。'" :type="allocationIssue?'warning':'success'" :closable="false"/>
    </template>
    <el-form-item label="处理依据" required><el-input v-model.trim="form.reason" type="textarea" maxlength="500"/></el-form-item><el-form-item label="核对凭证" required><el-input v-model.trim="form.evidence" type="textarea" maxlength="1000"/></el-form-item><el-form-item><el-checkbox v-model="form.confirmed">已核实实际包裹、商品数量、退款归属和仓库凭证</el-checkbox></el-form-item>
   </el-form><span slot="footer"><el-button @click="visible=false">返回</el-button><el-button type="primary" :loading="saving" :disabled="!form.confirmed||(action==='receipt'&&form.decision==='ALLOCATE'&&!!allocationIssue)||(action==='attach'&&(!checked||(candidates.length&&!form.join_parcel_id)))" @click="submit">确认提交</el-button></span>
  </el-dialog>
 </section>
</template>
<script>
import * as api from '@/api/order/refund'
import { parcelScope, parcelPending, scopePending, sourcePending, receiptText, allocationReason, allocationError, eligibleSources, receiptPayload, allocationMetadata, allocationOutcome } from './refundParcelPresentation'
export default {
 name:'RefundParcels',props:{refund:{type:Object,required:true},plans:{type:Array,default:()=>[]}},
 data:()=>({previewVisible:false,preview:{},previewConfirmed:false,previewParcel:null,previewEvent:null,parcelVisible:false,parcelId:null,documentVisible:false,documentAction:'',documentParcel:{},documentForm:{},rows:[],policy:{},stateLabels:{WAIT_LOGISTICS:'等待退回物流',WAIT_REVIEW:'等待审核',LINKED:'已关联退回包裹',NEED_CHECK:'合包待核对'},loading:false,saving:false,error:'',sequence:0,visible:false,action:'',form:{},selected:{},receipt:{},receiptLines:[],candidates:[],checked:false,checking:false,checkSequence:0,carriers:{SF:'顺丰',STO:'申通',YTO:'圆通',ZTO:'中通',YUNDA:'韵达',EMS:'EMS',OTHER:'其他'},transportLabels:{WAITING:'物流进度待登记',IN_TRANSIT:'退回在途',DELIVERED:'物流已签收（非仓库实收）',EXCEPTION:'物流异常'},dispatchLabels:{PENDING:'待下发',SENDING:'下发中',ACCEPTED:'仓库已接收',CANCELED:'安排已停止',FAILED:'下发失败',UNKNOWN:'结果待确认'},receiptLabels:{WAIT_ALLOCATION:'实收待分配，未分配部分未入账',ALLOCATED:'归属已确认，按各退款来源入账',REJECTED:'已拒绝本次回传入账',DOCUMENT:'按具体THK回传，实收与入账见单据'}}),
 computed:{detailRows(){return this.rows.filter(p=>String(p.id)===String(this.parcelId))},allocationIssue(){return this.action==='receipt'&&this.form.decision==='ALLOCATE'?allocationError(this.selected,this.receipt,this.form.allocations||[]):''}},
 watch:{refund(){this.load()}},created(){this.load()},beforeDestroy(){this.sequence++;this.checkSequence++},
 methods:{
  parcelScope,scopePending,sourcePending,receiptText,allocationReason,eligibleSources,allocationMetadata,allocationOutcome,
  allocationRows(p,e){const audit=allocationMetadata(e);if(audit.method==='RULE_PARTIAL'&&e.state==='ALLOCATED')return audit.rows||[];let allocations=[];try{allocations=typeof e.allocation_json==='string'?JSON.parse(e.allocation_json):e.allocation_json||[]}catch(_){return []}return allocations.map(a=>({...a,refund_sn:((p.members||[]).find(m=>Number(m.task_id)===Number(a.task_id))||{}).refund_sn||'来源待核对'}))},
  async previewAutomatic(p,e){this.saving=true;try{const r=await api.evaluateRefundReceipt(this.refund.id,p.id,e.id,{execute:false});this.preview=r.data;this.previewParcel=p.id;this.previewEvent=e.id;this.previewConfirmed=false;this.previewVisible=true}finally{this.saving=false}},
  async applyAutomatic(){if(!this.previewConfirmed||this.preview.status!=='READY'||this.saving)return;this.saving=true;try{await api.evaluateRefundReceipt(this.refund.id,this.previewParcel,this.previewEvent,{execute:true,confirmed:true,parcel_version:this.preview.parcel_version,policy_revision:this.preview.policy_revision});this.previewVisible=false;await this.load();this.$emit('changed');this.$message.success('已按当前规则分配，入账进度以各退款结果为准')}finally{this.saving=false}},
  removeAllocation(row){this.form.allocations.splice(this.form.allocations.indexOf(row),1)},
  openParcel(p){this.parcelId=p.id;this.parcelVisible=true},
  async openForPlan(plan){await this.load();const p=this.rows.find(p=>(p.members||[]).some(m=>Number(m.plan_id)===Number(plan)));if(p)this.openParcel(p);else this.$message.warning('未找到本计划关联的包裹，请核对关联进度')},
  async openFirst(){await this.load();const p=this.rows.find(p=>parcelPending(p))||this.rows[0];if(p)this.openParcel(p);else this.$message.info('尚未关联退回包裹，请先登记')},
  reportRemainder(p){const reported=this.reported(p),expected=this.expected(p),gap=expected-reported;const doc=p.warehouse_document||{};const final=['FULFILLED','COMPLETED'].includes(doc.warehouse_status)||(p.receipts||[]).some(e=>e.state==='WAIT_ALLOCATION'&&receiptPayload(e).ticketSn===doc.return_sn&&receiptPayload(e).complete);if(gap<0)return `当前回传超出合包计划 ${-gap} 件，请核对回传与实物`;if(!gap)return '当前回传数量已覆盖合包计划，实收归属与入账以处理结果为准';return final?`仓库已结束当前THK收货，按合包回传尚差 ${gap} 件，请核实差异`:`尚未回传 ${gap} 件，仓库尚未确认收货结束`},

  reported(p){return p.receipts.filter(e=>e.state!=='REJECTED').reduce((n,e)=>n+Number(e.quantity||0),0)},
  openDocument(p,action){this.documentParcel=p;this.documentAction=action;this.documentForm={reason:'',evidence:'',confirmed_shared:false,parcel_version:p.control_version};this.documentVisible=true},
  async submitDocument(){if(!this.documentForm.reason||!this.documentForm.evidence)return this.$message.warning('请填写处理依据和凭证');this.saving=true;try{await api.refundParcelDocument(this.refund.id,this.documentParcel.id,this.documentAction,this.documentForm);this.documentVisible=false;await this.load();this.$emit('changed')}finally{this.saving=false}},

  refundCount(p){return new Set(p.members.map(m=>m.refund_id)).size},sum(p,k){return p.members.reduce((n,m)=>n+Number(m[k]||0),0)},expected(p){const q={};p.members.forEach(m=>{q[m.plan_id]=Math.max(q[m.plan_id]||0,Number(m.quantity))});return Object.values(q).reduce((a,b)=>a+b,0)},waiting:parcelPending,
  async load(){const seq=++this.sequence;this.loading=true;try{const [r,p]=await Promise.all([api.refundParcels(this.refund.id),api.refundParcelPolicy(this.refund.id)]);if(seq===this.sequence){this.rows=r.data;this.policy=p.data;this.error='';this.$emit('loaded',this.rows)}}catch(_){if(seq===this.sequence)this.error='包裹信息加载失败，请刷新核对'}finally{if(seq===this.sequence)this.loading=false}},
  async retryAuto(){this.saving=true;try{await api.runRefundParcels(this.refund.id);await this.load();this.$emit('changed')}finally{this.saving=false}},
  openAutoLogistics(){this.openAttach();if(this.visible)this.action='auto-logistics'},
  base(){return {reason:'',evidence:'',confirmed:false}},openAttach(){if(!this.plans.length)return this.$message.warning('请先创建实际商品的退回计划');this.action='attach';this.form={...this.base(),plan_id:this.plans[0].id,carrier_code:'',waybill:'',join_parcel_id:null};this.clearCandidates();this.visible=true},clearCandidates(){this.checkSequence++;this.checked=false;this.checking=false;this.candidates=[];this.form.join_parcel_id=null},
  async checkCandidates(){if(!this.form.carrier_code||!this.form.waybill)return this.$message.warning('请填写快递编码和完整运单');const seq=++this.checkSequence;this.checking=true;try{const r=await api.refundParcelCandidates(this.refund.id,{carrier:this.form.carrier_code,waybill:this.form.waybill});if(seq===this.checkSequence){this.candidates=r.data;this.checked=true}}finally{if(seq===this.checkSequence)this.checking=false}},
  openTransport(p){this.action='transport';this.selected=p;this.form={...this.base(),transport_state:p.transport_state,control_version:p.control_version};this.visible=true},
  openReceipt(p,e){this.action='receipt';this.selected=p;this.receipt=e;try{const raw=typeof e.payload==='string'?JSON.parse(e.payload):e.payload;this.receiptLines=raw.lines||[]}catch(_){return this.$message.error('原回传无法读取，请联系管理员核对')}this.form={...this.base(),decision:'ALLOCATE',allocations:this.receiptLines.map((_,i)=>({line_index:i,task_id:null,good_qty:0,bad_qty:0}))};this.visible=true},
  async submit(){if(this.saving)return;if(!this.form.reason||!this.form.evidence)return this.$message.warning('请填写处理依据和核对凭证');if(this.action==='receipt'&&this.form.decision==='ALLOCATE'&&this.allocationIssue)return this.$message.warning(this.allocationIssue);this.saving=true;try{if(this.action==='attach'){const p=this.plans.find(p=>p.id===this.form.plan_id);await api.attachRefundParcel(this.refund.id,p.id,{...this.form,control_version:this.refund.control_version,plan_version:p.control_version})}else if(this.action==='auto-logistics'){const p=this.plans.find(p=>p.id===this.form.plan_id);await api.refundParcelManualLogistics(this.refund.id,p.id,{...this.form,control_version:this.refund.control_version,plan_version:p.control_version})}else if(this.action==='transport')await api.refundParcelTransport(this.refund.id,this.selected.id,this.form);else{const allocations=this.form.allocations.filter(a=>Number(a.good_qty)+Number(a.bad_qty)>0);if(this.form.decision==='ALLOCATE'&&(!allocations.length||allocations.some(a=>!a.task_id)))return this.$message.warning('请明确每份实收的退款和THK归属');await api.allocateRefundParcel(this.refund.id,this.selected.id,this.receipt.id,{...this.form,allocations})}this.visible=false;await this.load();this.$emit('changed')}finally{this.saving=false}}
 }
}
</script>
<style scoped>.refund-parcels{margin:24px 0}.flow{padding:14px;background:#f4f7fc;line-height:1.8;border-radius:6px;margin:12px 0}.heading{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.hint{color:#8290a4;font-size:12px;line-height:1.8}.parcel{padding:18px;border:1px solid #e1e8f0;border-radius:8px;margin:16px 0;overflow-wrap:anywhere}.summary,.source-line{background:#f4f7fc;border-radius:6px;padding:14px;margin:12px 0}.el-alert{margin:12px 0}.form{margin-top:20px}.allocation{display:flex;align-items:center;gap:8px;margin-top:12px;flex-wrap:wrap}.allocation .el-input-number{width:110px}.el-radio{white-space:normal;line-height:1.8}a{color:#1677ff}.own-scope{padding:12px 14px;background:#f4f7fc;border-radius:6px;line-height:1.8}.warning{color:#a46808;line-height:1.8}.parcel-workspace{padding:0 22px 24px}.parcel-detail{border:0;padding:0}.parcel-metrics{display:grid;grid-template-columns:repeat(5,1fr);gap:10px;margin:18px 0}.parcel-metrics>div{background:#f4f7fc;padding:16px;border-radius:8px}.parcel-metrics span{display:block;font-size:12px;color:#61728a}.parcel-metrics b{display:block;font-size:22px;margin-top:8px}.parcel-metrics .pending{background:#fff6e7;color:#a46808}.pending-receipt{border:1px solid #f0d4a0;background:#fffbf3;padding:12px 16px;margin:16px 0;border-radius:8px}@media(max-width:760px){.parcel-metrics{grid-template-columns:repeat(2,1fr)}}
.document-actions{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin:16px 0}.document-actions .el-button{margin:0}
</style>
